using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using WonderFleet.Domain.Entities;

namespace WonderFleet.Infrastructure.Persistence.Configurations;

// Keys are UUIDv7 generated by the application. ValueGeneratedNever makes EF INSERT (not UPDATE)
// new children discovered through navigations. Column names are snake_cased by ApplicationDbContext.

internal sealed class AdminUserConfiguration : IEntityTypeConfiguration<AdminUser>
{
    public void Configure(EntityTypeBuilder<AdminUser> b)
    {
        b.ToTable("admin_users");
        b.HasKey(x => x.Id);
        b.Property(x => x.Id).ValueGeneratedNever();
        b.HasMany(x => x.RefreshTokens).WithOne().HasForeignKey(t => t.AdminUserId).OnDelete(DeleteBehavior.Cascade);
    }
}

internal sealed class RefreshTokenConfiguration : IEntityTypeConfiguration<RefreshToken>
{
    public void Configure(EntityTypeBuilder<RefreshToken> b)
    {
        b.ToTable("refresh_tokens");
        b.HasKey(x => x.Id);
        b.Property(x => x.Id).ValueGeneratedNever();
    }
}

internal sealed class LogisticsPartnerConfiguration : IEntityTypeConfiguration<LogisticsPartner>
{
    public void Configure(EntityTypeBuilder<LogisticsPartner> b)
    {
        b.ToTable("logistics_partners");
        b.HasKey(x => x.Id);
        b.Property(x => x.Id).ValueGeneratedNever();
        b.HasMany(x => x.TruckTypes).WithOne().HasForeignKey(x => x.LogisticsPartnerId).OnDelete(DeleteBehavior.Cascade);
        b.HasMany(x => x.Corridors).WithOne().HasForeignKey(x => x.LogisticsPartnerId).OnDelete(DeleteBehavior.Cascade);
        b.HasMany(x => x.Documents).WithOne().HasForeignKey(x => x.LogisticsPartnerId).OnDelete(DeleteBehavior.Cascade);
        b.HasMany(x => x.Drivers).WithOne(x => x.LogisticsPartner).HasForeignKey(x => x.LogisticsPartnerId).OnDelete(DeleteBehavior.Restrict);
        b.HasMany(x => x.Vehicles).WithOne(x => x.LogisticsPartner).HasForeignKey(x => x.LogisticsPartnerId).OnDelete(DeleteBehavior.Restrict);
    }
}

