internal sealed class TripConfiguration : IEntityTypeConfiguration<Trip>
{
    public void Configure(EntityTypeBuilder<Trip> b)
    {
        b.ToTable("trips");
        b.HasKey(x => x.Id);
        b.Property(x => x.Id).ValueGeneratedNever();
        b.Ignore(x => x.IsEnded);
        b.Ignore(x => x.IsMoving);
        b.Ignore(x => x.Thresholds);
        b.Property(x => x.Version).HasColumnName("xmin").HasColumnType("xid").ValueGeneratedOnAddOrUpdate().IsConcurrencyToken();
        b.HasOne(x => x.Vehicle).WithMany().HasForeignKey(x => x.VehicleId).OnDelete(DeleteBehavior.Restrict);
        b.HasOne(x => x.Driver).WithMany().HasForeignKey(x => x.DriverId).OnDelete(DeleteBehavior.SetNull);
        b.HasOne(x => x.Device).WithMany().HasForeignKey(x => x.DeviceId).OnDelete(DeleteBehavior.SetNull);
        b.HasOne(x => x.LogisticsPartner).WithMany().HasForeignKey(x => x.LogisticsPartnerId).OnDelete(DeleteBehavior.Restrict);
        b.HasOne(x => x.AgroProcessor).WithMany().HasForeignKey(x => x.AgroProcessorId).OnDelete(DeleteBehavior.Restrict);
        b.HasOne<AdminUser>().WithMany().HasForeignKey(x => x.CreatedByAdminId).OnDelete(DeleteBehavior.SetNull);
        b.HasMany(x => x.Produce).WithOne().HasForeignKey(x => x.TripId).OnDelete(DeleteBehavior.Cascade);
    }
}

